class Timers { constructor () { this.next = 1; this.jobs = new Map() } setTimeout (fn, ms) { const id = this.next++; this.jobs.set(id, { fn, ms }); return id } clearTimeout (id) { this.jobs.delete(id) } setInterval (fn, ms) { return this.setTimeout(fn, ms) } clearInterval (id) { this.clearTimeout(id) } runNext () { const [id, job] = [...this.jobs].sort((a, b) => a[1].ms - b[1].ms)[0] || []; if (job) { this.jobs.delete(id); job.fn() } } }
class FakeSocket { static CONNECTING = 0; static OPEN = 1; static CLOSED = 3; static instances = []; constructor (url) { this.url = url; this.readyState = 0; this.sent = []; this.throwNextSend = false; FakeSocket.instances.push(this) } open () { this.readyState = 1; this.onopen?.() } send (value) { if (this.throwNextSend) { this.throwNextSend = false; throw new Error('synthetic-send-failure') } this.sent.push(value) } close () { this.readyState = 3; this.onclose?.() } message (value) { this.onmessage?.({ data: JSON.stringify(value) }) } }
class StubTransport { constructor () { this.epoch = 0; this.listeners = {}; this.sent = []; this.cancelled = [] } on (type, fn) { (this.listeners[type] ||= new Set()).add(fn); return () => this.listeners[type].delete(fn) } async connect () { this.epoch += 1; for (const fn of this.listeners.state || []) fn({ state: 'open', epoch: this.epoch }); return { epoch: this.epoch } } send (value, { key } = {}) { this.sent.push(value); if (key) for (const fn of this.listeners.sent || []) fn({ key, epoch: this.epoch }); return { sent: true, key } } cancel (key) { this.cancelled.push(key); return true } close () {} destroy () {} emit (type, value, epoch = this.epoch) { for (const fn of this.listeners[type] || []) fn({ data: JSON.stringify(value), epoch }) } }
class RelaySocket extends EventEmitter { constructor () { super(); this.OPEN = 1; this.readyState = 1; this.messages = [] } send (raw) { this.messages.push(JSON.parse(raw)) } terminate () { this.readyState = 3; this.emit('close') } receive (value) { this.emit('message', JSON.stringify(value)) } }
