  const bind = (socket, message) => { wss.emit('connection', socket, { socket: { remoteAddress: '127.0.0.13' } }); socket.receive({ type: 'client.hello', protocolVersion: 2, minProtocolVersion: 2, clientBuild: 'matrix', features: [] }); socket.receive(message) }
  const host = new RelaySocket(); bind(host, { type: 'room.resume', roomId: created.room.roomId, memberId: created.host.memberId, resumeToken: created.host.resumeToken, lastSeq: 0 }); const rotatedHostToken = host.messages.find(message => message.type === 'room.resumed').resumeToken
  const guest = new RelaySocket(); bind(guest, { type: 'room.join', roomSlug: created.room.roomSlug, inviteId: invite.inviteId, inviteSecret: invite.inviteSecret, displayName: 'Guest', lastSeq: 0 }); const guestId = guest.messages.find(message => message.type === 'room.joined').memberId
  const router = createCollaborationRouter({ repository: repo, onMembersInvalidated: result => relay.invalidateMembers(result) }); const layer = router.stack.find(item => item.route?.path === '/rooms/:roomId/invites/:inviteId' && item.route.methods.delete); const response = { statusCode: 0, body: null, status (code) { this.statusCode = code; return this }, json (body) { this.body = body; return this } }; layer.route.stack[0].handle({ params: { roomId: created.room.roomId, inviteId: invite.inviteId }, body: {}, get: name => ({ 'x-collaboration-member': created.host.memberId, 'x-collaboration-resume': rotatedHostToken }[name.toLowerCase()]) }, response)
  assert.equal(response.statusCode, 200); assert.deepEqual(response.body.invalidatedMemberIds, [guestId]); assert.equal(guest.readyState, 3); const afterRevoke = guest.messages.length; guest.receive({ type: 'room.recovery.request', roomId: created.room.roomId, lastSeq: 0 }); assert.equal(guest.messages.length, afterRevoke)
  host.receive({ protocolVersion: 2, type: 'chat.send', commandId: 'after-revoke', roomId: created.room.roomId, actorId: created.host.memberId, payload: { body: 'future', target: { artifactId: 'experience-runtime', artifactRevision: 1 } } }); assert.equal(guest.messages.some(message => message.event?.commandId === 'after-revoke'), false); relay.close(); repo.close()
